const CLASSIC_FULLCARD_ART = {"E_R_VP3_0": "data:image/webp;base64,", "E_R_VP2_0": "data:image/webp;base64,", "E_R_VP0_0": "data:image/webp;base64,", "E_R_M1_0": "data:image/webp;base64,", "E_R_M1_1": "data:image/webp;base64,", "E_R_M1_2": "data:image/webp;base64,", "E_Y_VP1_0": "data:image/webp;base64,", "E_Y_VP1_1": "data:image/webp;base64,", "E_Y_VP0_0": "data:image/webp;base64,", "E_Y_M2_0": "data:image/webp;base64,", "E_Y_M2_1": "data:image/webp;base64,", "E_Y_M1_0": "data:image/webp;base64,", "E_Y_M1_1": "data:image/webp;base64,", "E_Y_M1_2": "data:image/webp;base64,", "E_B_VP3_0": "data:image/webp;base64,", "E_B_VP2_0": "data:image/webp;base64,", "E_B_VP2_1": "data:image/webp;base64,", "E_B_M2_0": "data:image/webp;base64,", "E_B_M1_0": "data:image/webp;base64,", "E_B_M1_1": "data:image/webp;base64,", "E_B_M1_2": "data:image/webp;base64,", "E_B_M1_3": "data:image/webp;base64,", "E_G_VP3_0": "data:image/webp;base64,", "E_G_VP2_0": "data:image/webp;base64,", "E_G_VP2_LOW_0": "data:image/webp;base64,", "E_G_M1_0": "data:image/webp;base64,", "E_G_M1_1": "data:image/webp;base64,", "E_G_M1_2": "data:image/webp;base64,", "E_G_M1_3": "data:image/webp;base64,", "E_G_M1_4": "data:image/webp;base64,", "E_R_ENG": "data:image/webp;base64,"};
const CLASSIC_MINI_AVATAR = {"E_R_VP3_0": "data:image/webp;base64,", "E_R_VP2_0": "data:image/webp;base64,", "E_R_VP0_0": "data:image/webp;base64,", "E_R_M1_0": "data:image/webp;base64,", "E_R_M1_1": "data:image/webp;base64,", "E_R_M1_2": "data:image/webp;base64,", "E_Y_VP1_0": "data:image/webp;base64,", "E_Y_VP1_1": "data:image/webp;base64,", "E_Y_VP0_0": "data:image/webp;base64,", "E_Y_M2_0": "data:image/webp;base64,", "E_Y_M2_1": "data:image/webp;base64,", "E_Y_M1_0": "data:image/webp;base64,", "E_Y_M1_1": "data:image/webp;base64,", "E_Y_M1_2": "data:image/webp;base64,", "E_B_VP3_0": "data:image/webp;base64,", "E_B_VP2_0": "data:image/webp;base64,", "E_B_VP2_1": "data:image/webp;base64,", "E_B_M2_0": "data:image/webp;base64,", "E_B_M1_0": "data:image/webp;base64,", "E_B_M1_1": "data:image/webp;base64,", "E_B_M1_2": "data:image/webp;base64,", "E_B_M1_3": "data:image/webp;base64,", "E_G_VP3_0": "data:image/webp;base64,", "E_G_VP2_0": "data:image/webp;base64,", "E_G_VP2_LOW_0": "data:image/webp;base64,", "E_G_M1_0": "data:image/webp;base64,", "E_G_M1_1": "data:image/webp;base64,", "E_G_M1_2": "data:image/webp;base64,", "E_G_M1_3": "data:image/webp;base64,", "E_G_M1_4": "data:image/webp;base64,", "E_R_ENG": "data:image/webp;base64,"};
const GPT_FULLCARD_ART = {"E_G_VP3": "data:image/webp;base64,", "E_G_M1": "data:image/webp;base64,", "E_G_VP2_LOW": "data:image/webp;base64,", "E_G_VP2": "data:image/webp;base64,", "E_Y_VP1": "data:image/webp;base64,", "E_Y_M1": "data:image/webp;base64,", "E_Y_M2": "data:image/webp;base64,", "E_Y_VP0": "data:image/webp;base64,", "E_R_VP3": "data:image/webp;base64,", "E_R_ENG": "data:image/webp;base64,", "E_R_M1": "data:image/webp;base64,", "E_R_VP0": "data:image/webp;base64,", "E_R_VP2": "data:image/webp;base64,", "E_B_VP3": "data:image/webp;base64,", "E_B_M1": "data:image/webp;base64,", "E_B_M2": "data:image/webp;base64,", "E_B_VP2": "data:image/webp;base64,", "OUTSOURCED": "data:image/webp;base64,"};
const GPT_MINI_AVATAR = {"E_G_VP3": "data:image/webp;base64,", "E_G_M1": "data:image/webp;base64,", "E_G_VP2_LOW": "data:image/webp;base64,", "E_G_VP2": "data:image/webp;base64,", "E_Y_VP1": "data:image/webp;base64,", "E_Y_M1": "data:image/webp;base64,", "E_Y_M2": "data:image/webp;base64,", "E_Y_VP0": "data:image/webp;base64,", "E_R_VP3": "data:image/webp;base64,", "E_R_ENG": "data:image/webp;base64,", "E_R_M1": "data:image/webp;base64,", "E_R_VP0": "data:image/webp;base64,", "E_R_VP2": "data:image/webp;base64,", "E_B_VP3": "data:image/webp;base64,", "E_B_M1": "data:image/webp;base64,", "E_B_M2": "data:image/webp;base64,", "E_B_VP2": "data:image/webp;base64,", "OUTSOURCED": "data:image/webp;base64,"};

const __CARD_BLOB_URLS = { CLASSIC_BURN_RATE: {}, DEMON_CASTLE: {} };
const __MINI_BLOB_URLS = { CLASSIC_BURN_RATE: {}, DEMON_CASTLE: {} };

function dataUriToBlobUrl(dataUri) {
  if (!dataUri || !dataUri.startsWith("data:")) return dataUri || "";
  try {
    const parts = dataUri.split(",");
    const mimeMatch = parts[0].match(/:(.*?);/);
    const mime = mimeMatch ? mimeMatch[1] : "image/webp";
    const binStr = atob(parts[1]);
    const len = binStr.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binStr.charCodeAt(i);
    const blob = new Blob([bytes], { type: mime });
    return URL.createObjectURL(blob);
  } catch (e) {
    return dataUri;
  }
}

function initArtBlobCache() {
  if (window.__artBlobCacheReady) return;
  window.__artBlobCacheReady = true;

  Object.keys(CLASSIC_FULLCARD_ART).forEach((k) => {
    const url = dataUriToBlobUrl(CLASSIC_FULLCARD_ART[k]);
    __CARD_BLOB_URLS.CLASSIC_BURN_RATE[k] = url;
    const img = new Image();
    img.decoding = "async";
    img.src = url;
    if (img.decode) img.decode().catch(() => {});
  });
  Object.keys(CLASSIC_MINI_AVATAR).forEach((k) => {
    const url = dataUriToBlobUrl(CLASSIC_MINI_AVATAR[k]);
    __MINI_BLOB_URLS.CLASSIC_BURN_RATE[k] = url;
  });

  Object.keys(GPT_FULLCARD_ART).forEach((k) => {
    const url = dataUriToBlobUrl(GPT_FULLCARD_ART[k]);
    __CARD_BLOB_URLS.DEMON_CASTLE[k] = url;
    const img = new Image();
    img.decoding = "async";
    img.src = url;
    if (img.decode) img.decode().catch(() => {});
  });
  Object.keys(GPT_MINI_AVATAR).forEach((k) => {
    const url = dataUriToBlobUrl(GPT_MINI_AVATAR[k]);
    __MINI_BLOB_URLS.DEMON_CASTLE[k] = url;
  });
}

initArtBlobCache();

function resolveArtKey(keyOrCard) {
  if (!keyOrCard) return "";
  if (typeof keyOrCard === "object") {
    return keyOrCard.artKey || keyOrCard.tplId || "";
  }
  return String(keyOrCard);
}

function getBaseTplId(key) {
  return String(key || "").replace(/_\d+$/, "");
}

function getActiveThemeIdSafe() {
  if (typeof getActiveTheme === "function") {
    const t = getActiveTheme();
    if (t && t.id) return t.id;
  }
  return "CLASSIC_BURN_RATE";
}

function getCardArtSrc(keyOrCard) {
  const key = resolveArtKey(keyOrCard);
  const baseTpl = getBaseTplId(key);
  const themeId = getActiveThemeIdSafe();
  if (themeId === "DEMON_CASTLE") {
    return __CARD_BLOB_URLS.DEMON_CASTLE[baseTpl] || GPT_FULLCARD_ART[baseTpl] || "";
  }
  const zeroKey = baseTpl + "_0";
  return (
    __CARD_BLOB_URLS.CLASSIC_BURN_RATE[key] ||
    CLASSIC_FULLCARD_ART[key] ||
    __CARD_BLOB_URLS.CLASSIC_BURN_RATE[zeroKey] ||
    CLASSIC_FULLCARD_ART[zeroKey] ||
    __CARD_BLOB_URLS.CLASSIC_BURN_RATE[baseTpl] ||
    CLASSIC_FULLCARD_ART[baseTpl] ||
    ""
  );
}

function getMiniAvatarSrc(keyOrCard) {
  const key = resolveArtKey(keyOrCard);
  const baseTpl = getBaseTplId(key);
  const themeId = getActiveThemeIdSafe();
  if (themeId === "DEMON_CASTLE") {
    return __MINI_BLOB_URLS.DEMON_CASTLE[baseTpl] || GPT_MINI_AVATAR[baseTpl] || getCardArtSrc(baseTpl);
  }
  const zeroKey = baseTpl + "_0";
  return (
    __MINI_BLOB_URLS.CLASSIC_BURN_RATE[key] ||
    CLASSIC_MINI_AVATAR[key] ||
    __MINI_BLOB_URLS.CLASSIC_BURN_RATE[zeroKey] ||
    CLASSIC_MINI_AVATAR[zeroKey] ||
    __MINI_BLOB_URLS.CLASSIC_BURN_RATE[baseTpl] ||
    CLASSIC_MINI_AVATAR[baseTpl] ||
    getCardArtSrc(key)
  );
}

function getCardImgTag(keyOrCard, altText, clsName) {
  const src = getCardArtSrc(keyOrCard);
  return `<img src="${src}" alt="${altText || ""}" decoding="async" class="${clsName || ""}" />`;
}

window.getCardArtSrc = getCardArtSrc;
window.getMiniAvatarSrc = getMiniAvatarSrc;
window.getCardImgTag = getCardImgTag;
